18	
19	/**
20	 * Calcula o resumo da compra. A sequência do cálculo e a ordem das validações
21	 * são iguais para todo pedido e moram aqui; o que varia por caso mora nos enums
22	 * de domínio. As checagens seguem a ordem do enunciado e param no primeiro erro.
23	 */
24	@Service
25	public class CheckoutService {
26	
27	    public ResumoResponse calcular(ResumoRequest pedido) {
28	        // 1. Itens válidos → subtotal e peso do pedido.
29	        List<Item> itens = validarItens(pedido);
30	        BigDecimal subtotal = somarSubtotal(itens);
31	        BigDecimal pesoTotal = somarPeso(itens);
32	
33	        // 2. Nível do clube. 3. Região. 4. Modalidade de entrega.
34	        NivelClube clube = exigir(NivelClube.class, pedido.nivelClube(), "NIVEL_CLUBE_INVALIDO");
35	        Regiao regiao = exigir(Regiao.class, pedido.regiao(), "REGIAO_INVALIDA");
36	        ModalidadeEntrega modalidade =
37	                exigir(ModalidadeEntrega.class, pedido.modalidadeEntrega(), "MODALIDADE_INVALIDA");
38	
39	        // 5. Modalidade atende o pedido (ex.: motoboy acima de 5 kg).
40	        if (!modalidade.disponivelPara(pesoTotal)) {
41	            throw new CheckoutException("MODALIDADE_INDISPONIVEL");
42	        }
43	
44	        // Frete: pela modalidade, zerado quando o clube não paga frete.
45	        BigDecimal frete = clube.freteGratis()
46	                ? BigDecimal.ZERO.setScale(2)
47	                : Dinheiro.centavos(modalidade.freteBase(pesoTotal));
48	
49	        // 6. Cupom existe. 7. Cupom aplicável. (Pode não vir cupom.)
50	        BigDecimal descontoCupom = BigDecimal.ZERO.setScale(2);
51	        if (pedido.cupom() != null) {
52	            Cupom cupom = exigir(Cupom.class, pedido.cupom(), "CUPOM_INVALIDO");
53	            if (!cupom.aplicavel(subtotal)) {
54	                throw new CheckoutException("CUPOM_NAO_APLICAVEL");
55	            }
56	            descontoCupom = cupom.desconto(itens, subtotal, frete);
57	        }
58	
59	        // 8. Forma de pagamento. 9. Parcelamento permitido para a forma.
60	        FormaPagamento forma =
61	                exigir(FormaPagamento.class, pedido.formaPagamento(), "FORMA_PAGAMENTO_INVALIDA");
62	        int parcelas = pedido.parcelas() == null ? 1 : pedido.parcelas();
63	        if (!forma.parcelasValidas(parcelas)) {
64	            throw new CheckoutException("PARCELAMENTO_INVALIDO");
65	        }
66	
67	        // Seguro e total do pedido.
68	        BigDecimal seguro = regiao.seguro(subtotal);
69	        BigDecimal totalPedido = subtotal.subtract(descontoCupom).add(frete).add(seguro);
70	
71	        // 10. Forma atende o pedido (ex.: boleto acima de R$ 1.000).
72	        if (!forma.disponivelPara(totalPedido)) {
73	            throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
74	        }
75	
76	        // Pagamento e ajuste (final − total).
77	        ResultadoPagamento pagamento = forma.calcular(totalPedido, parcelas);
78	        BigDecimal ajuste = pagamento.totalFinal().subtract(totalPedido);
79	
80	        return new ResumoResponse(
81	                subtotal,
82	                descontoCupom,
83	                frete,
84	                modalidade.prazoDias(),
85	                seguro,
86	                ajuste,
87	                pagamento.totalFinal(),
88	                parcelas,
89	                pagamento.valorParcela(),
90	                clube.credito(subtotal),
91	                clube.temBrinde(subtotal));
92	    }
93	
94	    private List<Item> validarItens(ResumoRequest pedido) {
95	        List<ResumoRequest.ItemRequest> enviados = pedido.itens();
96	        if (enviados == null || enviados.isEmpty()) {
97	            throw new CheckoutException("PEDIDO_INVALIDO");
98	        }
99	        List<Item> itens = new ArrayList<>();
100	        for (ResumoRequest.ItemRequest item : enviados) {
101	            if (positivo(item.precoUnitario()) && item.quantidade() != null
102	                    && item.quantidade() > 0 && positivo(item.pesoKg())) {
103	                itens.add(new Item(item.nome(), item.precoUnitario(),
104	                        item.quantidade(), item.pesoKg()));
105	            } else {
106	                throw new CheckoutException("PEDIDO_INVALIDO");
107	            }
108	        }
109	        return itens;
110	    }
111	
112	    private boolean positivo(BigDecimal valor) {
113	        return valor != null && valor.compareTo(BigDecimal.ZERO) > 0;
114	    }
115	
116	    private BigDecimal somarSubtotal(List<Item> itens) {
117	        BigDecimal subtotal = BigDecimal.ZERO;
118	        for (Item item : itens) {
119	            subtotal = subtotal.add(item.totalLinha());
120	        }
121	        return Dinheiro.centavos(subtotal);
122	    }
123	
124	    private BigDecimal somarPeso(List<Item> itens) {
125	        BigDecimal peso = BigDecimal.ZERO;
126	        for (Item item : itens) {
127	            peso = peso.add(item.pesoLinha());
128	        }
129	        return peso;
130	    }
131	
132	    private <E extends Enum<E>> E exigir(Class<E> tipo, String valor, String codigoErro) {
133	        if (valor == null) {
134	            throw new CheckoutException(codigoErro);
135	        }
136	        try {
137	            return Enum.valueOf(tipo, valor);
138	        } catch (IllegalArgumentException naoExiste) {
139	            throw new CheckoutException(codigoErro);
140	        }
141	    }
142	}
