6	/**
7	 * Cupons promocionais. Cada um define sua condição de aplicação e seu desconto.
8	 * A assinatura recebe itens, subtotal e frete porque é o que o cupom mais
9	 * exigente precisa (FRETEGRATIS usa o frete; MENOS50 usa o subtotal;
10	 * LEVE3PAGUE2 usa os itens).
11	 */
12	public enum Cupom {
13	
14	    BEMVINDO10 {
15	        @Override
16	        public BigDecimal desconto(List<Item> itens, BigDecimal subtotal, BigDecimal frete) {
17	            return Dinheiro.centavos(subtotal.multiply(new BigDecimal("0.10")));
18	        }
19	    },
20	    MENOS50 {
21	        @Override
22	        public boolean aplicavel(BigDecimal subtotal) {
23	            return subtotal.compareTo(new BigDecimal("300.00")) >= 0;
24	        }
25	
26	        @Override
27	        public BigDecimal desconto(List<Item> itens, BigDecimal subtotal, BigDecimal frete) {
28	            return new BigDecimal("50.00");
29	        }
30	    },
31	    FRETEGRATIS {
32	        @Override
33	        public BigDecimal desconto(List<Item> itens, BigDecimal subtotal, BigDecimal frete) {
34	            return frete;
35	        }
36	    },
37	    LEVE3PAGUE2 {
38	        @Override
39	        public BigDecimal desconto(List<Item> itens, BigDecimal subtotal, BigDecimal frete) {
40	            BigDecimal total = BigDecimal.ZERO;
41	            for (Item item : itens) {
42	                int gratis = item.quantidade() / 3;
43	                total = total.add(item.precoUnitario().multiply(BigDecimal.valueOf(gratis)));
44	            }
45	            return Dinheiro.centavos(total);
46	        }
47	    };
48	
49	    /** Se o pedido cumpre a condição do cupom. */
50	    public boolean aplicavel(BigDecimal subtotal) {
51	        return true;
52	    }
53	
54	    /** Valor do desconto, já arredondado para centavos. */
55	    public abstract BigDecimal desconto(List<Item> itens, BigDecimal subtotal, BigDecimal frete);
56	}
