1	package com.loja.checkout.domain;
2	
3	import java.math.BigDecimal;
4	import java.math.MathContext;
5	import java.math.RoundingMode;
6	
7	/**
8	 * Formas de pagamento. Cada uma define quantas parcelas aceita, como chega no
9	 * valor final/parcela e se atende o pedido (boleto só até R$ 1.000).
10	 */
11	public enum FormaPagamento {
12	
13	    PIX {
14	        @Override
15	        public boolean parcelasValidas(int parcelas) {
16	            return parcelas == 1;
17	        }
18	
19	        @Override
20	        public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
21	            BigDecimal desconto = Dinheiro.centavos(totalPedido.multiply(new BigDecimal("0.05")));
22	            BigDecimal totalFinal = totalPedido.subtract(desconto);
23	            return new ResultadoPagamento(totalFinal, totalFinal);
24	        }
25	    },
26	    CARTAO {
27	        @Override
28	        public boolean parcelasValidas(int parcelas) {
29	            return parcelas >= 1 && parcelas <= 12;
30	        }
31	
32	        @Override
33	        public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
34	            if (parcelas <= 3) {
35	                BigDecimal parcela = Dinheiro.centavos(
36	                        totalPedido.divide(BigDecimal.valueOf(parcelas), MC));
37	                return new ResultadoPagamento(totalPedido, parcela);
38	            }
39	            // Tabela Price: parcela = total × taxa / (1 − (1 + taxa)^−n).
40	            BigDecimal fator = BigDecimal.ONE.add(TAXA_CARTAO).pow(parcelas);
41	            BigDecimal parcela = totalPedido.multiply(TAXA_CARTAO).multiply(fator)
42	                    .divide(fator.subtract(BigDecimal.ONE), MC);
43	            parcela = Dinheiro.centavos(parcela);
44	            BigDecimal totalFinal = parcela.multiply(BigDecimal.valueOf(parcelas));
45	            return new ResultadoPagamento(totalFinal, parcela);
46	        }
47	    },
48	    BOLETO {
49	        @Override
50	        public boolean parcelasValidas(int parcelas) {
51	            return parcelas == 1;
52	        }
53	
54	        @Override
55	        public boolean disponivelPara(BigDecimal totalPedido) {
56	            return totalPedido.compareTo(new BigDecimal("1000.00")) <= 0;
57	        }
58	
59	        @Override
60	        public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
61	            BigDecimal totalFinal = totalPedido.add(new BigDecimal("3.49"));
62	            return new ResultadoPagamento(totalFinal, totalFinal);
63	        }
64	    };
65	
66	    private static final BigDecimal TAXA_CARTAO = new BigDecimal("0.0199");
67	    private static final MathContext MC = new MathContext(20, RoundingMode.HALF_EVEN);
68	
69	    /** Se este número de parcelas é permitido para a forma de pagamento. */
70	    public abstract boolean parcelasValidas(int parcelas);
71	
72	    /** Se a forma atende o pedido com este total. */
73	    public boolean disponivelPara(BigDecimal totalPedido) {
74	        return true;
75	    }
76	
77	    /** Valor final e valor da parcela a partir do total do pedido. */
78	    public abstract ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas);
79	}
