12	
13	    @ExceptionHandler(CheckoutException.class)
14	    public ResponseEntity<ErroResponse> aoRecusar(CheckoutException ex) {
15	        return ResponseEntity.status(HttpStatus.UNPROCESSABLE_ENTITY)
16	                .body(new ErroResponse(ex.codigo()));
