18	
19	    /** Corpo ausente ou malformado é um pedido inválido. */
20	    @ExceptionHandler(HttpMessageNotReadableException.class)
21	    public ResponseEntity<ErroResponse> aoNaoLer(HttpMessageNotReadableException ex) {
22	        return ResponseEntity.status(HttpStatus.UNPROCESSABLE_ENTITY)
23	                .body(new ErroResponse("PEDIDO_INVALIDO"));
24	    }
